rect(0,0,W,H,'#29352b');for(let y=0;y<H;y+=16)for(let x=0;x<W;x+=16){let n=(Math.floor(x/16)*17+Math.floor(y/16)*31)%7;rect(x,y,15,15,n<2?'#2b382d':n<4?'#2d392e':'#2a362b');if(n===0){rect(x+3,y+5,1,1,'#394333');rect(x+11,y+12,2,1,'#344031')}if(n===4){rect(x+6,y+3,1,2,'#303a2b');rect(x+12,y+9,1,1,'#3b4532')}}
